    // eased march reads as a wobble) until it lands, eases out from that
    // same speed to a stand in STAND and stands. The top and right run with
    // m, the bottom and left (drawn left to right, top to bottom) against it,
    // so all four go clockwise.
    var a = land - t0, m1 = MARCH * a, m2 = m1 + MARCH * STAND / 2;
