      K.scan(K.q('.test-chip-slate'), 120 + off);
      sizes.forEach(function (c, i) { K.scan(c, 380 + off + 130 * i); });
      // the bands read the sizes on their own (until ~1.74s); as they
      // finish, the hand comes in from the right already moving, fading in
      // as it goes, in one move that lands on L a beat before the click.
      // The fade starts off a timer, the move's own clock: an animation
      // delay would count from the animation's first frame, which a busy
      // page start can push back, and the hand would pop in mid-flight.
      var l = lp || K.pt(L, 0.56, 0.6), dIn = K.reach(l, 1720 + off, { v0: [-0.24, 0.05], bow: -0.06 });
      K.sleep(Math.max(0, 1720 + off - dIn)).then(function () { K.fade(K.q('.test-cur'), 0, 1, 260); }, function () {});
      await K.land(1925 + off);
      // as the press lets go and L fills, on to Add to cart, where it rests
      // a beat before step 1 clicks it
